import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String REPORT_SCHEMA = System.getenv("REPORT_SCHEMA");

    // Anti-XSS filter for output encoding
    private String sanitizeOutput(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    // Validates report type against allowed enum
    private boolean isValidReportType(String type) {
        return Pattern.matches("^(daily|weekly|monthly|quarterly|annual)$", type);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String department = req.getParameter("dept");
        String fiscalYear = req.getParameter("fy");
        String sortCol = req.getParameter("sort");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate fiscal year is numeric
        if (fiscalYear != null && !Pattern.matches("^\\d{4}$", fiscalYear)) {
            resp.sendError(400, "Invalid fiscal year");
            return;
        }

        // Department validated against org directory
        if (department != null && !Pattern.matches("^[A-Z]{2,8}$", department)) {
            resp.sendError(400, "Invalid department code");
            return;
        }

        // Build query - sort column is from trusted UI dropdown
        String query = "SELECT id, title, amount, created_at FROM " + REPORT_SCHEMA + ".reports" +
                       " WHERE report_type = ? AND fiscal_year = ?" +
                       (department != null ? " AND dept_code = ?" : "") +
                       " ORDER BY " + sortCol;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, reportType);
            stmt.setString(2, fiscalYear);
            if (department != null) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("title", sanitizeOutput(rs.getString("title")));
                row.put("amount", rs.getDouble("amount"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            // Log but don't expose internal details
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
